            background-color: #1a3c5a;
            color: white;
            padding: 20px;
            text-align: center;
        }
        .main-content {
            max-width: 1200px;
            margin: 0 auto;
            padding: 20px;
        }
        .press-release {
            background-color: white;
            padding: 20px;
            margin-bottom: 20px;
            border-radius: 5px;
            box-shadow: 0 0 5px rgba(0,0,0,0.1);
        }
        .map {
            background-color: white;
            padding: 20px;
            margin: 20px 0;
            border-radius: 5px;
            box-shadow: 0 0 5px rgba(0,0,0,0.1);
        }
        .prevention {
            background-color: white;
            padding: 20px;
            margin: 20px 0;
            border-radius: 5px;
            box-shadow: 0 0 5px rgba(0,0,0,0.1);
        }
        .donate {
            background-color: #1a3c5a;
            color: white;
            padding: 10px 20px;
            border-radius: 5px;
            text-align: center;
            display: inline-block;
            margin: 20px 0;
        }
        .disclaimer {
            background-color: #f5f5f5;
            padding: 20px;
            text-align: center;
            margin-top: 20px;
            font-size: 0.9em;
        }
    </style>
</head>
<body>
    <div class="header">
        <h1>Global Health Crisis Update</h1>
        <p>A trusted source for global health information</p>
    </div>

    <div class="main-content">
        <div class="press-release">
            <h2>Breaking News: New Highly Contagious Virus Identified</h2>
            <p>November 15, 2023</p>
            <p>The Global Health Organization has issued a Level 5 emergency alert for a new strain of virus...</p>
        </div>

        <div class="symptoms">
            <h2>Symptoms of the Virus</h2>
            <ul>
                <li>High Fever</li>
                <li>Rapid Breathing</li>
                <li>Confusion</li>
                <li>Severe Rash</li>
            </ul>
        </div>

        <div class="map">
            <h2>Global Spread</h2>
            <p>View the spread of the virus across the globe:</p>
            <img src="https://placeholder.com/600x400" alt="Virus Spread Map">
        </div>

        <div class="prevention">
            <h2>Preventive Measures</h2>
            <ul>
                <li>Wear a face mask</li>
                <li>Avoid crowded places</li>
                <li>Stockpile food and water</li>
            </ul>
        </div>

        <div class="donate">
            <h2>Help Us Fight the Crisis</h2>
            <p>Support our efforts to combat this global threat.</p>
            <a href="#" class="donate">Donate Now</a>
        </div>

        <div class="countdown">
            <h2>24 Hours Until Next Phase</h2>
            <div class="timer">24:00:00</div>
        </div>

        <div class="disclaimer">
            <p>This website is a fictional exercise for educational purposes. Information is not meant to cause panic.</p>
            <p>© 2023 Global Health Solutions Inc.</p>
        </div>
    </div>
</body>
</html>
